schema_ddl:
create table shop.customers (id int generated by default as identity primary key, tenant int not null, name text, email text);
create table shop.orders (id int primary key, tenant int not null, customer int references shop.customers, total numeric, status text not null default 'open', created_at date not null default current_date);
-- Row-level security restricts you to rows where tenant = 1 (your tenant); new rows must also have tenant = 1. The customer id is generated automatically, do not supply it.
